import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Cpu } from 'lucide-react';
import modelComparison from '@/data/model_comparison.json';
import type { ModelRmse } from '@/types/charts';
import { axisTick, tooltipStyle } from './chartTheme';

/**
 * Model comparison RMSE — train.ipynb cells 17/21/22/26/28 (holdout RMSE for the four
 * baselines plus the tuned XGBoost production model), generated by
 * scripts/generate_chart_data.py. Lower is better; the production model is highlighted.
 */
export function ModelRmseChart() {
  const data = modelComparison as ModelRmse[];
  const production = 'XGBoost (production)';

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <Cpu className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Model Comparison</CardTitle>
          <CardDescription className="text-sm">Holdout RMSE — lower is better</CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={240}>
          <BarChart
            data={data}
            layout="vertical"
            margin={{ top: 10, right: 20, left: 10, bottom: 0 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" horizontal={false} />
            <XAxis type="number" tick={axisTick} axisLine={false} tickLine={false} />
            <YAxis
              type="category"
              dataKey="model"
              tick={{ ...axisTick, fontSize: 11 }}
              axisLine={false}
              tickLine={false}
              width={150}
            />
            <Tooltip
              cursor={{ fill: 'var(--accent)' }}
              contentStyle={tooltipStyle}
              formatter={(value) =>
                [`RMSE $${Number(value ?? 0).toFixed(2)}`, 'Holdout RMSE'] as [string, string]
              }
            />
            <Bar dataKey="rmse" radius={[0, 4, 4, 0]} maxBarSize={20}>
              {data.map((entry) => (
                <Cell
                  key={entry.model}
                  fill={entry.model === production ? 'var(--chart-2)' : 'var(--chart-1)'}
                />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
